import React, { useEffect, useState } from "react";
import { fetchDeliveries } from "../api/deliveryApi";
import { Link } from "react-router-dom";

interface Delivery {
  _id: string;
  customerId: string;
  driverId: string;
  status: string;
  location: {
    lat: number;
    lng: number;
  };
}

export default function DeliveryList() {
  const [deliveries, setDeliveries] = useState<Delivery[]>([]);

  useEffect(() => {
    fetchDeliveries()
      .then((res) => {
        console.log("📦 Deliveries fetched from API:", res.data); // DEBUG LINE
        setDeliveries(res.data);
      })
      .catch((err) => console.error("❌ Error fetching deliveries:", err));
  }, []);

  return (
    <div>
      <h2>All Deliveries</h2>

      {deliveries.length === 0 ? (
        <p>No deliveries available.</p>
      ) : (
        <ul>
          {deliveries.map((d) => (
            <li key={d._id}>
              <Link to={`/delivery/${d._id}`}>
                📦 Delivery for <strong>{d.customerId}</strong> – Status: <em>{d.status}</em>
              </Link>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
